class Account {
    private int balance = 100;

    public void setBalance(int b) {
        if(b >= 0) {
            balance = b;
        }
    }

    public int getBalance() {
        return balance;
    }
}

public class Main {
    public static void main(String[] args) {
        Account a = new Account();
        a.setBalance(-50);
        System.out.println(a.getBalance());
    }
}

