class Parent {
    String greeting = "Hello from Parent";

    void greet() {
        System.out.println("Parent method");
    }
}

class Child extends Parent {
    String greeting = "Hello from Child";
}

public class Main {
    public static void main(String[] args) {
        Parent p = new Child();
        System.out.println(p.greeting);
        p.greet();
    }
}

class Animal {
    void sound() {
        System.out.println("Some sound");
    }
}

class Cat extends Animal {
    void sound() {
        System.out.println("Meow");
    }
}

class Cow extends Animal {
    void sound() {
        System.out.println("Moo");
    }
}

public class Main {
    public static void main(String[] args) {
        Animal[] farm = new Animal[3];
        farm[0] = new Cat();
        farm[1] = new Cow();
        farm[2] = new Cat();
        for(Animal a : farm) {
            a.sound();
        }
    }
}
